  // The player's right-click on one of their OWN buildings. This runs the
  // real `applyCmd` case rather than re-implementing it, because the hooks
  // beside it that DO re-implement their command (orderCoil, orderCapture)
  // can pass while the path the player actually takes is broken — which is
  // how the miner-to-refinery order shipped broken twice.
  orderOwn: function (units, tgt) {
    if (!G || !tgt) return 0;
    applyCmd(G, ME, { t: 'own', u: idsOf(units), id: tgt.id });
    return units.length;
  },
  deploy: function (units, on) {
    units.forEach(function (u) { u.deployed = !!on; u.order = null; u.path = null; });
    return units.length;
  },
  rad: function (x, y) { return G ? radAt(G, x, y) : 0; },
  bombs: function () { return G ? G.bombs : []; },
  api3: { infest: infest, popDrone: popDrone, killDrone: killDrone, uspd: uspd,
          plantBomb: plantBomb, defuseBomb: defuseBomb, engineerDefuse: engineerDefuse,
          mindControl: mindControl, releaseMind: releaseMind, psiImmune: psiImmune,
          startErase: startErase, beginWarp: beginWarp, chronoDelayFor: chronoDelayFor,
          addRad: addRad, radAt: radAt, coilCharged: coilCharged, spyInfiltrate: spyInfiltrate,
          isHarv: isHarv, harvKey: harvKey, powered: powered, unitOrderFor: unitOrderFor,
          paxCapOf: paxCapOf, paxCount: paxCount, canBoard: canBoard, killPassengers: killPassengers,
          ifvModeOf: ifvModeOf, ifvSpec: ifvSpec, ifvTurret: ifvTurret,
          IFV_MODE: IFV_MODE, IFV_MODES: IFV_MODES, AI_TEAMS: AI_TEAMS, LAND_T: LAND_T,
          fire: fire, findRefinery: findRefinery, refDock: refDock,
          IVAN_BOMB_T: IVAN_BOMB_T, RAD_MAX: RAD_MAX, CHRONO_DELAY: CHRONO_DELAY,
          SPY_BLACKOUT: SPY_BLACKOUT, COIL_BOOST: COIL_BOOST, PARASITE_DMG: PARASITE_DMG },
  api2: { damageBridge: damageBridge, collapseSpan: collapseSpan, repairBridgeFrom: repairBridgeFrom,
          garrisonable: garrisonable, canOccupy: canOccupy, occCapOf: occCapOf, occCount: occCount,
          stepOreSpread: stepOreSpread, stepCrates: stepCrates, openCrate: openCrate,
          spySatUp: spySatUp, cloneVatsOf: cloneVatsOf, paraDrop: paraDrop, uspd: uspd,
          placeNeutrals: placeNeutrals, indexBridges: indexBridges, ORE_SPREAD_T: ORE_SPREAD_T }
