// Headless match runner used by the balance tests: no rendering, no audio.
// Both sides are driven by the same AI code (stepAI is side-agnostic), so
// "hard beats easy" measures the decision layers and nothing else.
// The audio harness drives this: every synth can be rendered offline into
// an OfflineAudioContext and measured, and `log` says which one fired for
// a given game event without anything having to be heard.
window.__rtsAudio = {
  SPEC: SPEC, REPORT: REPORT, VOX: VOX, VOXPAT: VOXPAT,
  kinds: function () { return Object.keys(PLAY); },
  log: function () { return aLog.slice(); },
  // Also drops the 70 ms per-sound throttle, the voice throttle and the
  // live-voice list, so a harness stepping 900 ticks in a millisecond is
  // not measuring wall-clock rate limits it never meant to exercise.
  clear: function () {
    aLog.length = 0; aStat.calls = aStat.played = aStat.dropped = 0; aStat.ms = 0;
    setSfxAt({}); setAckAt(0); live.length = 0;
  },
  stats: function () { return { calls: aStat.calls, played: aStat.played, dropped: aStat.dropped, ms: aStat.ms, live: live.length }; },
  music: function () { return MUS.state(); },
  ack: function (units, kind) { return unitAck(units, kind); },
  vol: function () { return { sfx: vol.sfx, voice: vol.voice, music: vol.music, on: soundOn, musicOn: musicOn }; },
  // One sound, rendered dry into `secs` of mono 44.1 kHz.
  render: function (kind, secs) {
    var OC = window.OfflineAudioContext || window.webkitOfflineAudioContext;
    if (!OC || !PLAY[kind]) return null;
    var c = new OC(1, Math.floor(44100 * (secs || 3)), 44100);
    var g = c.createGain(); g.gain.value = (SPEC[kind] ? SPEC[kind].v : 1);
    g.connect(c.destination);
    PLAY[kind](c, g, 0.02);
    return c.startRendering();
  },
  // One acknowledgement, likewise.
  renderVox: function (type, kind, sov, secs) {
    var OC = window.OfflineAudioContext || window.webkitOfflineAudioContext;
    var vx = VOX[type]; if (!OC || !vx || !vx.f) return null;
    var key = kind === 'select' ? 's' : kind === 'attack' ? 'a' : kind === 'deploy' ? 'd' : kind === 'harvest' ? 'h' : 'm';
    var pats = (vx[key] && vx[key].length) ? vx[key] : vx.m;
    if (!pats || !pats.length) return null;
    var c = new OC(1, Math.floor(44100 * (secs || 3)), 44100);
    var g = c.createGain(); g.gain.value = 1; g.connect(c.destination);
    voxLine(c, g, 0.02, vx.f * (sov ? 0.86 : 1), vx.b * (sov ? 0.94 : 1),
            Math.min(0.75, vx.r + (sov ? 0.12 : 0)), VOXPAT[pats[0]], sov ? 1.12 : 1);
    return c.startRendering();
  },
  renderMusic: function (theme, secs, heat) { return MUS.render(theme, secs || 3, heat); }
};

window.__rtsSim = function (seed, diffA, diffB, maxTicks, facA, facB, everyMinute) {
  var prevG = G, prevHeadless = headless, prevState = state;
  netStash();
  var prevNet = NET.active;                 // the menu/match client, parked
  setHeadless(true);
  try {
    var g = newState(seed >>> 0, diffB || 'normal', arguments[7], arguments[8]);
    g.side[P_HUMAN].fac = FACTIONS[facA] ? facA : 'dir';
    g.side[P_AI].fac = FACTIONS[facB] ? facB : 'col';
    g.ai = newAI(diffB || 'normal');      // player 1
    g.ai2 = newAI(diffA || 'normal');     // player 0
    g.focusFor[P_AI] = g.ai.cfg.focus;
    g.focusFor[P_HUMAN] = g.ai2.cfg.focus;
    [P_HUMAN, P_AI].forEach(function (p) { openingForce(g, p); });

    setG(g);
    var cap = maxTicks || 60 * 60 * 25;
    while (g.tick < cap && !g.over) {
      simStep(g);
      if ((g.tick % 120) === 0) sampleStuck(g);
      if (everyMinute && (g.tick % 3600) === 0) everyMinute(g);
    }
    return {
      ticks: g.tick, over: g.over,
      p0blds: g.blds.filter(function (b) { return !b.dead && b.p === P_HUMAN; }).length,
      p1blds: g.blds.filter(function (b) { return !b.dead && b.p === P_AI; }).length,
      p0units: countUnit(g, P_HUMAN, null), p1units: countUnit(g, P_AI, null),
      p0credits: Math.round(g.side[P_HUMAN].credits),
      p1credits: Math.round(g.side[P_AI].credits),
      p0made: g.side[P_HUMAN].made, p1made: g.side[P_AI].made,
      p0fac: g.side[P_HUMAN].fac, p1fac: g.side[P_AI].fac,
      p0mix: bldMix(g, P_HUMAN), p1mix: bldMix(g, P_AI),
      p0q: queueState(g, P_HUMAN), p1q: queueState(g, P_AI),
      stuck: countStuck(g)
    };
  } finally {
    setG(prevG); setHeadless(prevHeadless); setState(prevState);
    if (prevNet) netLoad(prevNet); else NET.active = null;
  }
};

// Stuck detection has to be sampled over TIME. Checking "did it move on the
// final frame" flags a unit that merely paused to fire, and misses one that
// has been wedged against a rock for four minutes.
function sampleStuck(g) {
  for (var i = 0; i < g.units.length; i++) {
    var u = g.units[i];
    if (u.dead) continue;
    var moved = Math.abs(u.x - u.lastx) > 0.02 || Math.abs(u.y - u.lasty) > 0.02;
    var wants = (!!u.order || u.state === 'tomine' || u.state === 'toref') &&
                u.state !== 'mining';
    // A unit standing still because it is SHOOTING is doing its job. Only
    // a unit that wants to be somewhere and is not getting there is stuck.
    // (Slow, slow-firing units like the Mammoth sit in cooldown for over a
    // second at a time and were being counted as frozen.)
    var fighting = u.cool > 0;
    if (wants && !moved && !fighting) u.stuck++; else u.stuck = 0;
    u.lastx = u.x; u.lasty = u.y;
  }
}

function bldMix(g, p) {
  var m = {};
  for (var i = 0; i < g.blds.length; i++) {
    var b = g.blds[i];
    if (!b.dead && b.p === p) m[b.type] = (m[b.type] || 0) + 1;
  }
  return m;
}

function queueState(g, p) {
  var q = g.side[p].queues;
  return { b: q.b.list.slice(), ready: q.b.ready, i: q.i.list.slice(), v: q.v.list.slice(), a: q.a.list.slice() };
}

function countStuck(g) {
  var n = 0;
  for (var i = 0; i < g.units.length; i++) {
    if (!g.units[i].dead && g.units[i].stuck >= 3) n++;
  }
  return n;
}

window.__rtsFocus = function (gx, gy) { centerOn(gx, gy); clampCam(); };

